# file: more_itertools/more.py
# class: (함수 정의)
def gray_product(*iterables, repeat=1):
    """
    Cartesian product in Gray code order.
    """
    # 이터레이터를 리스트로 변환하여 여러 번 반복 가능하게 함
    pools = [list(iterable) for iterable in iterables]
    if repeat != 1:
        pools = pools * repeat

    # 나머지 로직...
    if not all(pools):
        return

    def gray_product_helper(pools):
        if len(pools) == 1:
            for x in pools[0]:
                yield (x,)
        else:
            for p in gray_product_helper(pools[:-1]):
                if len(p) % 2 == 0:
                    for x in pools[-1]:
                        yield p + (x,)
                else:
                    for x in reversed(pools[-1]):
                        yield p + (x,)

    for product in gray_product_helper(pools):
        yield product
```

