# file: more_itertools/more.py
def gray_product(*iterables, repeat=1):
    pools = [list(it) for it in iterables] * repeat
    if not all(pools):
        return

    def helper(pools):
        if not pools:
            yield ()
        else:
            for p in helper(pools[:-1]):
                if len(p) % 2 == 0:
                    for x in pools[-1]:
                        yield p + (x,)
                else:
                    for x in reversed(pools[-1]):
                        yield p + (x,)

    yield from helper(pools)
```

