# file: more_itertools/more.py
def gray_product(*iterables, repeat=1):
    """Return the Cartesian product of the input iterables, with the
    elements in Gray code order.

        >>> list(gray_product([1, 2], [3, 4]))
        [(1, 3), (2, 3), (2, 4), (1, 4)]
        >>> list(gray_product([1, 2], [3, 4], repeat=2))
        [(1, 3), (1, 4), (2, 4), (2, 3), (2, 3), (2, 4), (1, 4), (1, 3)]

    Gray code order means that each successive tuple differs from the
    previous one by a single element.

    This function produces the same results as :func:`itertools.product`,
    except the order of the tuples is different.

    """
    if repeat < 1:
        raise ValueError('repeat must be greater than 0')

    pools = [tuple(it) for it in tee(chain.from_iterable(
        [iterables] * repeat
    ), repeat * len(iterables))]

    if any(not pool for pool in pools):
        return

    def gray_product_helper(pools):
        if len(pools) == 1:
            for item in pools[0]:
                yield (item,)
        else:
            for item in pools[0]:
                for rest in gray_product_helper(pools[1:]):
                    yield (item,) + rest

    for combo in gray_product_helper(pools):
        yield combo
